class Solution {
public:
    int splitArray(vector<int>& nums, int k) {
        long long lo = 0, hi = 0;
        for (int x : nums) {
            lo = max(lo, (long long)x);
            hi += x;
        }
        while (lo < hi) {
            long long mid = lo + (hi - lo) / 2;
            int count = 1;
            long long cur = 0;
            for (int x : nums) {
                if (cur + x > mid) {
                    count++;
                    cur = x;
                } else {
                    cur += x;
                }
            }
            if (count <= k) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return (int)lo;
    }
};
